import numpy as np
import random

def task_func(length=10000, seed=0):
    if length < 0:
        raise ValueError("length must be non-negative")

    rng = random.Random(seed)
    steps = np.fromiter((rng.choice((-1, 1)) for _ in range(length)), dtype=int, count=length)
    return np.concatenate(([0], np.cumsum(steps, dtype=int)))
